style>\n.skills-section {\n  font-family: \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif;\n  padding: 20px;\n  max-width: 1200px;\n  margin: auto;\n}\n.skills-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));\n  gap: 25px;\n}\n.skill-card {\n  background: #f9f9f9;\n  border-left: 5px solid #00aaff;\n  padding: 20px;\n  border-radius: 10px;\n  box-shadow: 0 2px 6px rgba(0,0,0,0.08);\n}\n.skill-card h3 {\n  font-size: 18px;\n  margin-bottom: 15px;\n  color: #005577;\n  border-bottom: 1px solid #ddd;\n  padding-bottom: 8px;\n}\n.skill-card ul {\n  list-style: none;\n  padding-left: 0;\n  margin: 0;\n}\n.skill-card ul li {\n  padding: 6px 0;\n  color: #333;\n  font-size: 15px;\n  border-bottom: 1px dashed #ddd;\n}\n.skill-card ul li:last-child {\n  border-bottom: none;\n}\n</style>\n\n<div class=\"skills-section\">\n  <h2 style=\"text-align:center; color:#003344;\">Technical Skills</h2>\n  <div class=\"skills-grid\">\n\n    <div class=\"skill-card\">\n      <h3>Operating Systems</h3>\n      <ul>\n        <li>Windows</li>\n        <li>Linux (Ubuntu, CentOS)</li>\n        <li>macOS</li>\n      </ul>\n    </div>\n\n    <div class=\"skill-card\">\n      <h3>DevOps & Automation</h3>\n      <ul>\n        <li>Git & GitHub</li>\n        <li>Jenkins</li>\n        <li>Ansible</li>\n        <li>Terraform</li>\n        <li>Docker</li>\n        <li>Kubernetes</li>\n      </ul>\n    </div>\n\n    <div class=\"skill-card\">\n      <h3>Cloud & Infrastructure</h3>\n      <ul>\n        <li>AWS</li>\n        <li>VPC</li>\n        <li>Cloudflare</li>\n        <li>Google Workspace Admin</li>\n        <li>Office 365 Admin</li>\n      </ul>\n    </div>\n\n    <div class=\"skill-card\">\n      <h3>Monitoring & Security</h3>\n      <ul>\n        <li>CloudWatch</li>\n        <li>Pulse Secure</li>\n        <li>Checkpoint VPN</li>\n        <li>Antivirus Management</li>\n        <li>SCCM (Client Mgmt & Troubleshooting)</li>\n      </ul>\n    </div>\n\n    <div class=\"skill-card\">\n      <h3>Database & Web Servers</h3>\n      <ul>\n        <li>SQL Server (Management, Backup & Restore)</li>\n        <li>Elasticsearch</li>\n        <li>IIS Web Server</li>\n      </ul>\n    </div>\n\n    <div class=\"skill-card\">\n      <h3>Ticketing & Tools</h3>\n      <ul>\n        <li>BMC Remedy</li>\n        <li>VDI & Thin Client Imaging</li>\n        <li>Citrix Receiver</li>\n        <li>Outlook 2013 & 365 Setup</li>\n      </ul>\n    </div>\n\n    <div class=\"skill-card\">\n      <h3>Networking & Maintenance</h3>\n      <ul>\n        <li>Ping, Traceroute</li>\n        <li>Weekly Antivirus & Patch Updates</li>\n        <li>System Evaluation & Hardware Optimization</li>\n        <li>User Profile & Email ID Management</li>\n      </ul>\n    </div>\n\n  </div>\n</div>\n\n<!-- /wp:html --></div></div>\n<!-- /wp:kadence/column -->\n<!-- /wp:kadence/rowlayout -->\n\n<!-- wp:kadence/rowlayout {\"uniqueID\":\"75_4ae3f7-2a\",\"columns\":1,\"colLayout\":\"equal\",\"inheritMaxWidth\":true,\"kbVersion\":2} -->\n<!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"75_623966-c4\",\"kbVersion\":2} -->\n<div class=\"wp-block-kadence-column kadence-column75_623966-c4\"><div class=\"kt-inside-inner-col\"></div></div>\n<!-- /wp:kadence/column -->\n<!-- /wp:kadence/rowlayout -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'Home', '', 'inherit', 'closed', 'closed', '', '75-revision-v1', '', '', '2025-08-02 12:15:16', '2025-08-02 12:15:16', '', 75, 'http://localhost/amgdigital.space/?p=1704', 0, 'revision', '', 0);
